// [의사코드] 저장된 배치·반입 명세를 따라 모델/시각 배치와 검수 결과를 재현한다.
// [코딩]
// Pseudocode: snapshot existing collisions and ceiling poses, add visual-only assets,
// then reopen each independent scene and compare the protected data before rendering.
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using UnityEngine.SceneManagement;
using UnityEditor;
using UnityEditor.SceneManagement;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

public static class PlacementSession {
 public static string Work=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../tmp/Asset_Placement_20261103"));
 public const string Root="Assets/Afrer_Seconds/";
 public static string[] Scenes=>AssetDatabase.FindAssets("t:Scene",new[]{Root+"01.Scenes/Stage"}).Select(AssetDatabase.GUIDToAssetPath).OrderBy(x=>x).ToArray();
 public static Transform[] All(Scene s)=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();
 public static string P(Transform t)=>t.parent==null?t.name:P(t.parent)+"/"+t.name;
 public static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 public static float[] Q(Quaternion q)=>new[]{q.x,q.y,q.z,q.w};
 public static Bounds B(GameObject g) {var rr=g.GetComponentsInChildren<Renderer>(true).Where(r=>r.enabled&&r.gameObject.activeInHierarchy).ToArray();if(rr.Length==0)throw new Exception("No active renderer "+g.name);var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);return b;}
 static object ColliderRecord(Collider c) {object shape=null;if(c is BoxCollider b)shape=new{center=V(b.center),size=V(b.size)};else if(c is CapsuleCollider a)shape=new{center=V(a.center),radius=a.radius,height=a.height,direction=a.direction};else if(c is SphereCollider z)shape=new{center=V(z.center),radius=z.radius};else if(c is CharacterController cc)shape=new{center=V(cc.center),height=cc.height,radius=cc.radius,slope=cc.slopeLimit,step=cc.stepOffset};else if(c is MeshCollider m)shape=new{mesh=AssetDatabase.GetAssetPath(m.sharedMesh),name=m.sharedMesh?m.sharedMesh.name:"null",convex=m.convex};return new{path=P(c.transform),type=c.GetType().Name,pos=V(c.transform.position),rot=Q(c.transform.rotation),scale=V(c.transform.lossyScale),enabled=c.enabled,trigger=c.isTrigger,shape=shape};}
 static JObject Snapshot(Scene s) {Physics.SyncTransforms();var all=All(s);return JObject.Parse(JsonConvert.SerializeObject(new{scene=s.path,colliders=all.SelectMany(t=>t.GetComponents<Collider>()).Select(ColliderRecord).OrderBy(x=>JsonConvert.SerializeObject(x)).ToArray(),ceilings=all.Where(t=>t.name.IndexOf("Ceiling",StringComparison.OrdinalIgnoreCase)>=0).Select(t=>new{path=P(t),pos=V(t.localPosition),rot=Q(t.localRotation),scale=V(t.localScale)}).OrderBy(x=>x.path).ToArray()}));}
 static bool CeilingMatch(JToken before,JToken after) {var keys=new HashSet<string>(before.Select(x=>(string)x["path"]));return JToken.DeepEquals(before,new JArray(after.Where(x=>keys.Contains((string)x["path"]))));}
 public static JArray ColliderSnapshot(Scene s)=>(JArray)Snapshot(s)["colliders"];
 static bool ColliderMatch(JToken before,JToken after,string scene){string file=Path.Combine(Work,"authorized_collider_changes.json");if(!File.Exists(file))return JToken.DeepEquals(before,after);var a=JObject.Parse(File.ReadAllText(file));if((string)a["scene"]!=scene)return JToken.DeepEquals(before,after);var expected=(JArray)before.DeepClone();foreach(var change in a["changes"]){var old=expected.First(x=>JToken.DeepEquals(x,change["before"]));old.Replace(change["after"].DeepClone());}foreach(var c in a["added"])expected.Add(c.DeepClone());return JToken.DeepEquals(new JArray(expected.OrderBy(x=>x.ToString(Newtonsoft.Json.Formatting.None))),after);}
 public static string Capture(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var scenes=new JArray();foreach(var p in Scenes){var s=EditorSceneManager.OpenScene(p,OpenSceneMode.Single);scenes.Add(Snapshot(s));}File.WriteAllText(Path.Combine(Work,"protected_before.json"),scenes.ToString());EditorSceneManager.OpenScene(Scenes.First(p=>p.Contains("B5")));return "Captured 6 scenes: Collider definitions and ceiling poses";}
 public static Transform Group(Transform parent,string name){var t=parent.Find(name);if(t)return t;var g=new GameObject(name);g.transform.SetParent(parent,false);return g.transform;}
 public static string Floor(string path)=>path.Contains("B5")?"B5":path.Contains("B4")?"B4":path.Contains("B3")?"B3":path.Contains("B2")?"B2":path.Contains("B1")?"B1":"1F";
 public static void Fit(GameObject g,Vector3 maxSize,Vector3 bottomCenter,float yaw) {g.transform.rotation=Quaternion.Euler(0,yaw,0);var b=B(g);float k=Mathf.Min(maxSize.x/b.size.x,maxSize.y/b.size.y,maxSize.z/b.size.z);g.transform.localScale*=k;b=B(g);g.transform.position+=bottomCenter-new Vector3(b.center.x,b.min.y,b.center.z);}
 static void VisualFlags(GameObject g){foreach(var t in g.GetComponentsInChildren<Transform>(true))GameObjectUtility.SetStaticEditorFlags(t.gameObject,StaticEditorFlags.BatchingStatic|StaticEditorFlags.ReflectionProbeStatic);foreach(var r in g.GetComponentsInChildren<Renderer>(true)){r.shadowCastingMode=ShadowCastingMode.On;r.receiveShadows=true;}}
 public static string Apply(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var plan=JArray.Parse(File.ReadAllText(Path.Combine(Work,"placements.json")));var assets=JArray.Parse(File.ReadAllText(Path.Combine(Work,"unity_import_facts.json")));var before=JArray.Parse(File.ReadAllText(Path.Combine(Work,"protected_before.json")));var facts=new List<object>();
 foreach(var path in Scenes){var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var all=All(scene);var placed=new List<object>();foreach(JObject p in plan.Where(p=>(string)p["floor"]==Floor(path))){var room=all.FirstOrDefault(t=>t.name==(string)p["room"]);if(!room)throw new Exception("Room missing "+p["room"]);var group=Group(room,"Asset_Completion_Visuals");string name=(string)p["key"];if(group.Find(name))throw new Exception("Already placed "+name);var asset=assets.First(a=>(string)a["name"]==(string)p["asset"]);var prefab=AssetDatabase.LoadAssetAtPath<GameObject>((string)asset["prefab"]);var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,scene);go.name=name;go.transform.SetParent(group,false);var pos=p["pos"].ToObject<float[]>();var max=p["max"].ToObject<float[]>();Fit(go,new Vector3(max[0],max[1],max[2]),room.TransformPoint(new Vector3(pos[0],pos[1],pos[2])),(float)p["yaw"]);if((bool?)p["exact"]==true){var oldBounds=B(go);go.transform.localScale=Vector3.Scale(go.transform.localScale,new Vector3(max[0]/oldBounds.size.x,max[1]/oldBounds.size.y,max[2]/oldBounds.size.z));var exactBounds=B(go);go.transform.position+=room.TransformPoint(new Vector3(pos[0],pos[1],pos[2]))-new Vector3(exactBounds.center.x,exactBounds.min.y,exactBounds.center.z);}if((bool?)p["center"]==true)go.transform.position-=Vector3.up*B(go).size.y*.5f;if(p["top"]!=null)go.transform.position+=Vector3.up*(room.TransformPoint(new Vector3(0,(float)p["top"],0)).y-B(go).max.y);VisualFlags(go);var b=B(go);placed.Add(new{name=name,asset=(string)p["asset"],room=P(room),center=V(b.center),size=V(b.size),bottom=b.min.y});}
 // Keep the existing light-crate Collider and only give the marker a lightweight tote shell.
 if(Floor(path)=="B2")AddRoof(scene,assets);
 var tote=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"05.Model/Props/Common/P13_LogisticsTote.prefab");int crates=0;foreach(var t in all.Where(t=>t.name.StartsWith("LightCrate"))){if(t.Find("LightCrate_AssetVisual"))continue;var renderer=t.GetComponent<MeshRenderer>();if(!renderer||!renderer.enabled)continue;var b=renderer.bounds;var go=(GameObject)PrefabUtility.InstantiatePrefab(tote,scene);go.name="LightCrate_AssetVisual";go.transform.SetParent(t,false);go.transform.localScale=Vector3.one;Fit(go,b.size*.98f,new Vector3(b.center.x,b.min.y,b.center.z),t.eulerAngles.y);renderer.enabled=false;VisualFlags(go);crates++;}
 // Correct a cabinet that was above floor height outside the raised platform footprint.
 if(Floor(path)=="B4"){var cabinet=all.FirstOrDefault(t=>t.name.StartsWith("P04_RecordsCabinet"));if(cabinet&&Mathf.Abs(cabinet.localPosition.x)>3.5f&&cabinet.localPosition.y>2){var v=cabinet.localPosition;v.y=0;cabinet.localPosition=v;}}
 var now=Snapshot(scene);var previous=before.First(b=>(string)b["scene"]==path);if(!ColliderMatch(previous["colliders"],now["colliders"],path))throw new Exception("Protected Collider changed "+path);if(!CeilingMatch(previous["ceilings"],now["ceilings"]))throw new Exception("Protected ceiling pose changed "+path);
 EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);facts.Add(new{floor=Floor(path),scene=path,newModels=placed,lightCrateVisuals=crates});}
 File.WriteAllText(Path.Combine(Work,"placement_facts.json"),JsonConvert.SerializeObject(facts,Formatting.Indented));EditorSceneManager.OpenScene(Scenes.First(p=>p.Contains("B5")));return "Visual assets placed; protected Collider and ceiling snapshots match";}
 public static void Render(Scene s,string file,Vector3 pos,Vector3 target,bool overview){var hidden=new List<Renderer>();foreach(var cc in All(s).SelectMany(t=>t.GetComponents<CharacterController>()))foreach(var r in cc.GetComponentsInChildren<Renderer>(true))if(r.enabled){r.enabled=false;hidden.Add(r);}if(overview)foreach(var t in All(s).Where(t=>t.name.IndexOf("Ceiling",StringComparison.OrdinalIgnoreCase)>=0))foreach(var r in t.GetComponentsInChildren<Renderer>())if(r.enabled){r.enabled=false;hidden.Add(r);}var g=new GameObject("Temporary_AssetReviewCamera");g.hideFlags=HideFlags.HideAndDontSave;var c=g.AddComponent<Camera>();c.enabled=false;c.transform.position=pos;c.transform.LookAt(target);c.fieldOfView=57;c.nearClipPlane=.05f;c.farClipPlane=180;c.clearFlags=CameraClearFlags.Skybox;c.useOcclusionCulling=false;c.allowHDR=true;c.GetUniversalAdditionalCameraData().renderPostProcessing=true;var rt=new RenderTexture(1600,1000,24,RenderTextureFormat.ARGB32);var prev=RenderTexture.active;
 try{c.targetTexture=rt;c.Render();c.Render();c.Render();RenderTexture.active=rt;var image=new Texture2D(1600,1000,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1600,1000),0,0);image.Apply();File.WriteAllBytes(Path.Combine(Work,file),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}finally{c.targetTexture=null;RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);foreach(var r in hidden)r.enabled=true;}}
 public static void AddRoof(Scene scene,JArray assets){var host=All(scene).First(t=>t.name=="Ceiling"&&P(t).Contains("Room07_CentrifugeHall"));var renderer=host.GetComponent<Renderer>();var original=renderer.bounds;var room=host.parent;var group=Group(room,"Asset_Completion_Visuals");var prefab=AssetDatabase.LoadAssetAtPath<GameObject>((string)assets.First(a=>(string)a["name"]=="Env_RoofPanel")["prefab"]);int nx=3,nz=4;for(int x=0;x<nx;x++)for(int z=0;z<nz;z++){var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,scene);go.name="RoofPanel_"+x+"_"+z;go.transform.SetParent(group,false);go.transform.rotation=Quaternion.Euler(180,0,0);var b=B(go);var size=new Vector3(original.size.x/nx,original.size.y,original.size.z/nz);go.transform.localScale=Vector3.Scale(go.transform.localScale,new Vector3(size.x/b.size.x,size.y/b.size.y,size.z/b.size.z));b=B(go);var target=new Vector3(original.min.x+size.x*(x+.5f),original.center.y,original.min.z+size.z*(z+.5f));go.transform.position+=target-b.center;VisualFlags(go);}renderer.enabled=false;}
 public static string Verify(){var before=JArray.Parse(File.ReadAllText(Path.Combine(Work,"protected_before.json")));var results=new List<object>();foreach(var path in Scenes){var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var all=All(scene);var now=Snapshot(scene);var previous=before.First(b=>(string)b["scene"]==path);bool collisions=ColliderMatch(previous["colliders"],now["colliders"],path);bool ceiling=CeilingMatch(previous["ceilings"],now["ceilings"]);int missing=all.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));var broken=all.SelectMany(t=>t.GetComponents<MeshFilter>()).Where(m=>m.sharedMesh==null).Select(m=>P(m.transform)).ToArray();var badMat=all.SelectMany(t=>t.GetComponents<Renderer>()).Where(r=>r.enabled&&r.sharedMaterials.Any(m=>m==null||m.shader==null||m.shader.name=="Hidden/InternalErrorShader")).Select(r=>P(r.transform)).ToArray();var visual=all.Where(t=>t.parent&&t.parent.name=="Asset_Completion_Visuals").ToArray();var coll=visual.Sum(t=>t.GetComponentsInChildren<Collider>().Length);Physics.SyncTransforms();var overlaps=visual.Select(t=>new{t=t,b=B(t.gameObject)}).Select(x=>new{name=x.t.name,colliders=Physics.OverlapBox(x.b.center,x.b.extents*.94f,Quaternion.identity,~0,QueryTriggerInteraction.Ignore).Where(c=>c is not CharacterController).Select(c=>P(c.transform)).ToArray()}).Where(x=>x.colliders.Length>0).ToArray();var f=Floor(path);Render(scene,f+"_overview.png",f=="B5"?new Vector3(22,32,26):new Vector3(23,32,22),f=="B5"?new Vector3(3,0,-4):new Vector3(0,0,-8),true);
 Vector3 eye,target;switch(f){case "B5":eye=new Vector3(1,1.8f,7);target=new Vector3(-5,1.5f,2);break;case "B4":eye=new Vector3(0,1.8f,-16);target=new Vector3(4.5f,1.2f,-24);break;case "B3":eye=new Vector3(1.2f,1.8f,4.8f);target=new Vector3(-4,1.8f,-3);break;case "B2":eye=new Vector3(1.2f,1.8f,3.2f);target=new Vector3(-4.5f,1.3f,5);break;case "B1":eye=new Vector3(1,1.8f,6);target=new Vector3(-5,1.5f,3);break;default:eye=new Vector3(0,1.8f,6);target=new Vector3(5,1.5f,-3);break;}Render(scene,f+"_interior.png",eye,target,false);
 results.Add(new{floor=f,protectedCollidersMatchApprovedBaseline=collisions,ceilingPosesPreserved=ceiling,missingScripts=missing,missingMeshes=broken,badMaterials=badMat,newVisualColliders=coll,overlaps=overlaps,newInstances=visual.Length});if(!collisions||!ceiling||missing!=0||broken.Length!=0||badMat.Length!=0||coll!=0){File.WriteAllText(Path.Combine(Work,"verification.json"),JsonConvert.SerializeObject(results,Formatting.Indented));throw new Exception("Scene verification failed "+path+" Collider="+collisions+" Ceiling="+ceiling+" Scripts="+missing+" Mesh="+broken.Length+" Materials="+badMat.Length+" NewCollider="+coll);}}
 File.WriteAllText(Path.Combine(Work,"verification.json"),JsonConvert.SerializeObject(results,Formatting.Indented));EditorSceneManager.OpenScene(Scenes.First(p=>p.Contains("B5")));return "6 scenes reopened, protected data/materials/meshes/scripts checked and review renders captured";}
}

// [주석] 검수 자료의 작업 순서와 최신 경로표를 확인한 뒤 사용한다.
